B.b7W=new A.jS("data_object",B.bbl,".json","Strukturierte ELDAT-Daten im JSON-Format. Kommt bei einigen modernen Forstbetrieben vor.",null,null)
B.b7U=new A.jS("code",B.Bo,".xml","XML-Variante von ELDAT \u2014 wird ebenfalls automatisch eingelesen.",null,null)
